//! Screenshots of whole HTML documents against Chrome 156 (miaskiewicz/turbo-html2pdf#29):
//! `<head>` styles cascade, `<body>` has its 8px UA margin and the root/body background
//! fills the canvas.
//!
//! The control is turbo-dom-layout's `tests/fixtures/html_document_chrome156.json`
//! (generated by turbo-dom's `scripts/html-document-chrome-control.mjs`): each case's
//! `canvas` is Chrome's pixel at (1278, 798), below all of the case's content.
use turbo_dom_raster::{screenshot_png, Viewport};

const VIEWPORT: Viewport = Viewport {
    width: 1280,
    height: 800,
};

fn pixel(png: &[u8], x: u32, y: u32) -> String {
    let pm = tiny_skia::Pixmap::decode_png(png).expect("decode");
    let p = pm.pixel(x, y).expect("in bounds");
    format!("#{:02x}{:02x}{:02x}", p.red(), p.green(), p.blue())
}

#[test]
fn canvas_matches_chrome_156() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../turbo-dom-layout/tests/fixtures/html_document_chrome156.json"
    );
    let fixture: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("fixture")).unwrap();
    let mut failures = Vec::new();
    for case in fixture["cases"].as_array().unwrap() {
        let png = screenshot_png(case["html"].as_str().unwrap(), VIEWPORT).expect("png");
        let got = pixel(&png, 1278, 798);
        if got != case["canvas"].as_str().unwrap() {
            failures.push(format!(
                "{}: canvas {got}, Chrome {}",
                case["id"], case["canvas"]
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn head_styles_paint_inside_the_body_margin() {
    let html = "<!DOCTYPE html><html><head><style>div{background:#ff0000;width:50px;height:50px}</style></head><body><div></div></body></html>";
    let png = screenshot_png(html, VIEWPORT).expect("png");
    assert_eq!(pixel(&png, 4, 4), "#ffffff", "inside body's 8px margin");
    assert_eq!(
        pixel(&png, 8, 8),
        "#ff0000",
        "the head-styled box at (8, 8)"
    );
    assert_eq!(pixel(&png, 57, 57), "#ff0000");
    assert_eq!(pixel(&png, 58, 58), "#ffffff");
}

#[test]
fn inert_markup_never_paints_or_cascades() {
    // `<script>` source and `<template>` content are never painted; a `<noscript>`
    // `<style>` is inert (the layout parses with scripting on, as the hydrated page ran).
    let html = "<html><head><noscript><style>div{display:none}</style></noscript></head>\
        <body style=\"margin:0\"><script>document.write('XXXXXXXXXXXXXXXX')</script>\
        <template><p>XXXXXXXX</p></template><div style=\"background:#ff0000;height:10px\"></div></body></html>";
    let png = screenshot_png(html, VIEWPORT).expect("png");
    assert_eq!(
        pixel(&png, 5, 5),
        "#ff0000",
        "the div is the first painted box"
    );
    assert_eq!(pixel(&png, 5, 15), "#ffffff");
}
